export function byId<T>(items: readonly T[], id: number): T | undefined {
  return items.find((item) => item.id === id);
}

import { byId } from '../src/byid.ts';
type User = { id: number; name: string };
const users: User[] = [{ id: 1, name: 'An' }];
const found: User | undefined = byId(users, 1); // keeps the User type
export { found };

import { byId } from '../src/byid.ts';
const labs = [{ code: 'BE-201', name: 'Backend Lab 1' }]; // no id
const x = byId(labs, 1); // expect TS2345
export { x };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { byId } from '../src/byid.ts';

const users = [{ id: 1, name: 'An' }, { id: 2, name: 'Binh' }];
test('found', () => assert.equal(byId(users, 2)?.name, 'Binh'));
test('missing', () => assert.equal(byId(users, 9), undefined));

