export { id, role };

import { getProp } from '../src/get.ts';
import type { User } from '../src/user.ts';
declare const an: User;
const x = getProp(an, 'ghost'); // expect TS2345
export { x };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { getProp } from '../src/get.ts';

test('getProp', () => assert.equal(getProp({ id: 1, name: 'An' }, 'name'), 'An'));

