starterCodeJson.code:
export function pluck(items: any[], key: string): any[] {
  return items.map((item) => item[key]);
}

import { pluck } from '../src/pluck.ts';
import type { User } from '../src/user.ts';
declare const users: User[];
const ids: number[] = pluck(users, 'id');
const names: string[] = pluck(users, 'name');
export { ids, names };

import { pluck } from '../src/pluck.ts';
import type { User } from '../src/user.ts';
declare const users: User[];
const g = pluck(users, 'ghost'); // expect TS2345
export { g };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { pluck } from '../src/pluck.ts';

const users = [{ id: 1, name: 'An' }, { id: 2, name: 'Binh' }];
test('pluck id', () => assert.deepEqual(pluck(users, 'id'), [1, 2]));
test('pluck name', () => assert.deepEqual(pluck(users, 'name'), ['An', 'Binh']));

